package br.com.tapeteskalke.service; import br.com.tapeteskalke.repository.*; import java.math.BigDecimal; import java.math.RoundingMode; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
// Resultado por competência (receita − CMV − despesas) e, à parte, o fluxo de caixa (receita − compras − despesas).
// Salários vêm das despesas do tipo SALARIOS, para não somar duas vezes o que já foi lançado como despesa.
@Service public class RelatorioService { private final VendaRepository vendas; private final CompraRepository compras; private final DespesaRepository despesas; public RelatorioService(VendaRepository vendas,CompraRepository compras,DespesaRepository despesas){this.vendas=vendas;this.compras=compras;this.despesas=despesas;} @Transactional(readOnly=true) public Map<String,BigDecimal> financial(LocalDate start,LocalDate end){var receita=vendas.totalFinalized(start,end);var cmv=vendas.costOfGoodsSold(start,end).setScale(2,RoundingMode.HALF_UP);var totalCompras=compras.totalFinalized(start,end);var salarios=despesas.totalByTipo("SALARIOS",start,end);var outras=despesas.totalByPeriod(start,end).subtract(salarios);var lucroBruto=receita.subtract(cmv);var m=new LinkedHashMap<String,BigDecimal>();m.put("receita",receita);m.put("custoMercadoriaVendida",cmv);m.put("lucroBruto",lucroBruto);m.put("salarios",salarios);m.put("outrasDespesas",outras);m.put("lucroLiquido",lucroBruto.subtract(salarios).subtract(outras));m.put("compras",totalCompras);m.put("fluxoCaixa",receita.subtract(totalCompras).subtract(salarios).subtract(outras));return m;} }
